import heapq


class JournalError(ValueError):
    pass


def _ids(value, default):
    """Validate an optional array of change IDs, defaulting to empty."""
    if value is None:
        return default
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    seen = set()
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        seen.add(item)
    return seen


def read_changes(records):
    """Validate records and collapse identical duplicates to one entry."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = _ids(row.get("depends_on"), set())
        entry = {"id": row["id"], "component": row["component"], "units": row["units"],
                 "depends_on": depends_on}
        known = changes.get(entry["id"])
        if known is None:
            changes[entry["id"]] = entry
        elif known != entry:
            raise JournalError("conflicting-change")
    return [changes[key] for key in sorted(changes)]


def read_applied(value):
    """Validate the persisted journal of already applied change IDs."""
    return _ids(value, set())


MAX_RETAIN = 1024


def read_retain(value):
    """Validate the optional retain list; malformed input is invalid-retain."""
    if value is None:
        return []
    if not isinstance(value, list) or len(value) > MAX_RETAIN:
        raise JournalError("invalid-retain")
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-retain")
    return list(value)


def check_retain(graph, applied, retain):
    """Retain IDs must be applied, and their applied dependencies are kept too.

    `graph` maps change ID to its normalized record, so the walk uses the same
    dependency data as ordering does.
    """
    if len(retain) != len(set(retain)):
        raise JournalError("invalid-retain")
    if not set(retain) <= applied:
        raise JournalError("invalid-retain")
    retained = set(retain)
    parents = {change_id: row["depends_on"] for change_id, row in graph.items()}
    stack = list(retained)
    while stack:
        for dependency in parents[stack.pop()]:
            if dependency in applied and dependency not in retained:
                retained.add(dependency)
                stack.append(dependency)
    return retained


def check_graph(changes, applied):
    """Reject unknown references and cycles before any ordering work."""
    known = {row["id"] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")


def order(changes):
    """Return the full topological order, breaking ties lexicographically."""
    pending = {row["id"]: set(row["depends_on"]) for row in changes}
    children = {row["id"]: [] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            children[dependency].append(row["id"])
    ready = [change_id for change_id, deps in pending.items() if not deps]
    heapq.heapify(ready)
    ordered = []
    while ready:
        current = heapq.heappop(ready)
        ordered.append(current)
        for child in children[current]:
            deps = pending[child]
            deps.discard(current)
            if not deps:
                heapq.heappush(ready, child)
    if len(ordered) != len(pending):
        raise JournalError("dependency-cycle")
    return ordered

