"""Compose policy and journal data into a plan."""
from journal import (
    JournalError,
    check_graph,
    check_retain,
    order,
    read_applied,
    read_changes,
    read_retain,
)
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def _units_of(changes, actions):
    return sum(changes[change_id]["units"] for change_id in actions)


def _validated(request):
    """Run policy first, then journal validation, in a fixed order."""
    budget = limit_for(request)
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied"))
    retain = read_retain(request.get("retain"))
    check_graph(changes, applied)
    ordered = order(changes)
    return budget, changes, applied, retain, ordered


def _rollback(graph, applied, retain, ordered):
    retained = check_retain(graph, applied, retain)
    actions = [change_id for change_id in reversed(ordered)
               if change_id in applied and change_id not in retained]
    return success(actions, _units_of(graph, actions))


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget, changes, applied, retain, ordered = _validated(request)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    graph = {row["id"]: row for row in changes}
    if request["action"] == "rollback":
        try:
            return _rollback(graph, applied, retain, ordered)
        except JournalError as exc:
            return failure(str(exc))
    # `retain` is rollback-only: ignored here, never applied to a plan.
    actions = [change_id for change_id in ordered if change_id not in applied]
    units = _units_of(graph, actions)
    if units > budget:
        return failure("budget-exceeded")
    return success(actions, units)

