journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _texts(value):
    """Return a list of nonempty strings, or None when the input is malformed."""
    if not isinstance(value, list):
        return None
    for item in value:
        if not isinstance(item, str) or not item:
            return None
    return list(value)


def read_changes(records):
    """Validate change records and collapse identical duplicates.

    Each returned record is ``{"id", "component", "units", "depends_on"}``
    where ``depends_on`` is a deduplicated list of dependency IDs. Records are
    ordered by ID so downstream graph construction is deterministic.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    by_id = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        ident = row.get("id")
        component = row.get("component")
        units = row.get("units")
        if (not isinstance(ident, str) or not ident
                or not isinstance(component, str) or not component
                or type(units) is not int or units < 1):
            raise JournalError("invalid-change")
        depends_on = _texts(row.get("depends_on", []))
        if depends_on is None:
            raise JournalError("invalid-change")
        record = {
            "id": ident,
            "component": component,
            "units": units,
            "depends_on": sorted(set(depends_on)),
        }
        seen = by_id.get(ident)
        if seen is None:
            by_id[ident] = record
        elif seen != record:
            raise JournalError("conflicting-change")
    return [by_id[ident] for ident in sorted(by_id)]


def read_applied(applied, changes):
    """Validate the persisted journal of applied change IDs."""
    ids = _texts(applied)
    if ids is None:
        raise JournalError("invalid-change")
    known = {row["id"] for row in changes}
    for ident in ids:
        if ident not in known:
            raise JournalError("unknown-dependency")
    return set(ids)

planner.py.text:
"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Return change IDs in deterministic dependency order.

    Among currently eligible changes the lexicographically smallest ID is
    emitted first. A cycle anywhere raises ``dependency-cycle`` even if the
    cycle contains already applied changes.
    """
    order = [row["id"] for row in changes]
    known = set(order)
    dependents = {ident: [] for ident in order}
    pending = {}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
            dependents[dep].append(row["id"])
        pending[row["id"]] = len(row["depends_on"])

    eligible = [ident for ident in order if pending[ident] == 0]
    heapq.heapify(eligible)
    result = []
    while eligible:
        ident = heapq.heappop(eligible)
        result.append(ident)
        for child in dependents[ident]:
            pending[child] -= 1
            if pending[child] == 0:
                heapq.heappush(eligible, child)
    if len(result) != len(order):
        raise JournalError("dependency-cycle")
    return result


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), changes)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if request["action"] == "rollback":
        # The budget is validated but never caps a rollback.
        actions = [ident for ident in reversed(order) if ident in applied]
    else:
        actions = [ident for ident in order if ident not in applied]
        if sum(units_by_id[ident] for ident in actions) > budget:
            return failure("budget-exceeded")
    return {
        "status": "ok",
        "actions": actions,
        "units": sum(units_by_id[ident] for ident in actions),
    }

policy.py.text:
"""Validate release policy before computing actions."""

ENVIRONMENTS = frozenset({"staging", "production"})
ACTIONS = frozenset({"plan", "rollback"})


class PolicyError(ValueError):
    pass


def limit_for(request):
    """Return the budget after validating environment, action and budget."""
    if request.get("environment") not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return budget

