    by_id = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        ident = row.get("id")
        component = row.get("component")
        units = row.get("units")
        if (not isinstance(ident, str) or not ident
                or not isinstance(component, str) or not component
                or type(units) is not int or units < 1):
            raise JournalError("invalid-change")
        depends_on = _texts(row.get("depends_on", []))
        if depends_on is None:
            raise JournalError("invalid-change")
        record = {
            "id": ident,
            "component": component,
            "units": units,
            "depends_on": sorted(set(depends_on)),
        }
        seen = by_id.get(ident)
        if seen is None:
            by_id[ident] = record
        elif seen != record:
            raise JournalError("conflicting-change")
    return [by_id[ident] for ident in sorted(by_id)]


def read_applied(applied, changes):
    """Validate the persisted journal of applied change IDs."""
    ids = _texts(applied)
    if ids is None:
        raise JournalError("invalid-change")
    known = {row["id"] for row in changes}
    for ident in ids:
        if ident not in known:
            raise JournalError("unknown-dependency")
    return set(ids)


def read_retain(retain, applied):
    """Validate the rollback retain list against the persisted journal.

    ``retain`` defaults to an empty list and must name only already applied
    changes; anything malformed or not applied raises ``invalid-retain``.
    """
    ids = _texts(retain)
    if ids is None:
        raise JournalError("invalid-retain")
    for ident in ids:
        if ident not in applied:
            raise JournalError("invalid-retain")
    return set(ids)

