"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, assert_open, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Return change IDs in deterministic dependency order.

    Among currently eligible changes the lexicographically smallest ID is
    emitted first. A cycle anywhere raises ``dependency-cycle`` even if the
    cycle contains already applied changes.
    """
    order = [row["id"] for row in changes]
    known = set(order)
    dependents = {ident: [] for ident in order}
    pending = {}
    for row in changes:
        for dep in row["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
            dependents[dep].append(row["id"])
        pending[row["id"]] = len(row["depends_on"])

    eligible = [ident for ident in order if pending[ident] == 0]
    heapq.heapify(eligible)
    result = []
    while eligible:
        ident = heapq.heappop(eligible)
        result.append(ident)
        for child in dependents[ident]:
            pending[child] -= 1
            if pending[child] == 0:
                heapq.heappush(eligible, child)
    if len(result) != len(order):
        raise JournalError("dependency-cycle")
    return result


def applied_closure(ids, changes, applied):
    """Return ``ids`` plus the applied dependencies they transitively require."""
    dependencies = {row["id"]: row["depends_on"] for row in changes}
    kept = set()
    stack = list(ids)
    while stack:
        ident = stack.pop()
        if ident in kept:
            continue
        kept.add(ident)
        stack.extend(dep for dep in dependencies[ident] if dep in applied)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        assert_open(request)
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), changes)
        order = topological_order(changes)
        retain = read_retain(request.get("retain", []), applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if request["action"] == "rollback":
        # The budget is validated but never caps a rollback.
        kept = applied_closure(retain, changes, applied)
        actions = [ident for ident in reversed(order)
                   if ident in applied and ident not in kept]
    else:
        actions = [ident for ident in order if ident not in applied]
        if sum(units_by_id[ident] for ident in actions) > budget:
            return failure("budget-exceeded")
    return {
        "status": "ok",
        "actions": actions,
        "units": sum(units_by_id[ident] for ident in actions),
    }

policy.py.text:
"""Validate release policy before computing actions."""

ENVIRONMENTS = frozenset({"staging", "production"})
ACTIONS = frozenset({"plan", "rollback"})
STAGING_BUDGET_CAP = 3


class PolicyError(ValueError):
    pass


def assert_open(request):
    """Refuse frozen environments before any graph or change validation."""
    environment = request.get("environment")
    if environment == "production":
        raise PolicyError("production-frozen")
    if environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")


def limit_for(request):
    """Validate action and budget, then return the effective budget.

    Call ``assert_open`` first so a frozen environment wins over these errors.
    """
    if request.get("action") not in ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return min(budget, STAGING_BUDGET_CAP)

