"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _graph(changes):
    """Build the dependency graph and return a stable topological order.

    Every dependency must name a known change (`unknown-dependency`) and the
    whole graph is checked for cycles (`dependency-cycle`) before any ordering
    is handed out, so a plan is never partially emitted from a broken graph.
    Eligibility is decided with a heap keyed by ID and neighbours are visited in
    sorted order, which makes the order a function of the input set alone - the
    same request always yields byte-identical actions.
    """
    units = {row["id"]: row["units"] for row in changes}
    depends = {row["id"]: row["depends_on"] for row in changes}
    for change_id in depends:
        for target in depends[change_id]:
            if target not in units:
                raise JournalError("unknown-dependency")

    waiting = {change_id: set(depends[change_id]) for change_id in depends}
    blocks = {change_id: [] for change_id in depends}
    for change_id, targets in depends.items():
        for target in targets:
            blocks[target].append(change_id)

    ready = [change_id for change_id, pending in waiting.items() if not pending]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in sorted(blocks[change_id]):
            waiting[dependent].discard(change_id)
            if not waiting[dependent]:
                heapq.heappush(ready, dependent)
    if len(order) != len(depends):
        # Any change still waiting sits on (or behind) a cycle.
        raise JournalError("dependency-cycle")
    return order, units


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []), {row["id"] for row in changes})
        order, units = _graph(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    if request["action"] == "rollback":
        # Rollback undoes the full release in reverse order; the budget field is
        # validated by policy but deliberately does not cap it, because an
        # emergency rollback must not be left half-done by a small quota.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
        return {"status": "ok", "actions": actions, "units": sum(units[i] for i in actions)}

    # Replay first: applied entries satisfy dependencies but add no new units.
    actions = [change_id for change_id in order if change_id not in applied]
    emitted = sum(units[change_id] for change_id in actions)
    if emitted > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": emitted}

